// Package argparse is a small command-line argument parser supporting boolean
// flags, flags with values, positional arguments and generated help text.
//
// Supported syntax:
//
//	--flag            boolean flag
//	--flag=false      boolean flag with explicit value
//	--name value      value flag
//	--name=value      value flag
//	-f                short boolean flag
//	-abc              cluster of short flags
//	-n value, -nvalue short value flag (may end a cluster)
//	--                everything after is positional
//	-h, --help        built in; Parse returns ErrHelp
package argparse

import (
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
	"unicode/utf8"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	long  string
	short rune   // 0 if the flag has no short form
	help  string
	meta  string // value placeholder shown in help; empty for boolean flags
	def   string // default shown in help; empty to omit
	set   func(string) error
}

type positional struct {
	name     string
	help     string
	required bool
	dst      *string
}

// Parser holds a set of flag and positional argument definitions.
type Parser struct {
	name string
	desc string

	flags []*flag
	long  map[string]*flag
	short map[rune]*flag

	pos      []*positional
	restName string
	restHelp string
	rest     *[]string
}

// New returns a Parser for a program with the given name and description.
func New(name, description string) *Parser {
	return &Parser{
		name:  name,
		desc:  description,
		long:  map[string]*flag{},
		short: map[rune]*flag{},
	}
}

// Bool defines a boolean flag. Pass 0 as short for a flag with no short form.
func (p *Parser) Bool(long string, short rune, help string) *bool {
	v := new(bool)
	p.add(&flag{long: long, short: short, help: help, set: func(s string) error {
		b, err := strconv.ParseBool(s)
		if err != nil {
			return errors.New("expected true or false")
		}
		*v = b
		return nil
	}})
	return v
}

// String defines a flag taking a string value.
func (p *Parser) String(long string, short rune, def, help string) *string {
	v := new(string)
	*v = def
	f := &flag{long: long, short: short, help: help, meta: "string", set: func(s string) error {
		*v = s
		return nil
	}}
	if def != "" {
		f.def = strconv.Quote(def)
	}
	p.add(f)
	return v
}

// Int defines a flag taking an integer value.
func (p *Parser) Int(long string, short rune, def int, help string) *int {
	v := new(int)
	*v = def
	p.add(&flag{long: long, short: short, help: help, meta: "int", def: strconv.Itoa(def), set: func(s string) error {
		n, err := strconv.Atoi(s)
		if err != nil {
			return errors.New("expected an integer")
		}
		*v = n
		return nil
	}})
	return v
}

// Arg defines a required positional argument.
func (p *Parser) Arg(name, help string) *string {
	return p.addPositional(name, help, true)
}

// OptionalArg defines an optional positional argument. Optional arguments
// must be defined after all required ones.
func (p *Parser) OptionalArg(name, help string) *string {
	return p.addPositional(name, help, false)
}

// Rest collects any positional arguments beyond those defined with Arg and
// OptionalArg. Without it, extra positional arguments are an error.
func (p *Parser) Rest(name, help string) *[]string {
	if p.rest != nil {
		panic("argparse: Rest defined twice")
	}
	p.restName, p.restHelp = name, help
	p.rest = new([]string)
	return p.rest
}

// Definition mistakes are programmer errors, so add and addPositional panic.

func (p *Parser) add(f *flag) {
	if f.long == "" || strings.HasPrefix(f.long, "-") || strings.ContainsAny(f.long, "= ") {
		panic(fmt.Sprintf("argparse: invalid flag name %q", f.long))
	}
	if f.long == "help" {
		panic("argparse: --help is built in")
	}
	if p.long[f.long] != nil {
		panic(fmt.Sprintf("argparse: flag --%s defined twice", f.long))
	}
	p.long[f.long] = f
	if f.short != 0 {
		if p.short[f.short] != nil {
			panic(fmt.Sprintf("argparse: flag -%c defined twice", f.short))
		}
		p.short[f.short] = f
	}
	p.flags = append(p.flags, f)
}

func (p *Parser) addPositional(name, help string, required bool) *string {
	if required && len(p.pos) > 0 && !p.pos[len(p.pos)-1].required {
		panic(fmt.Sprintf("argparse: required argument %q follows an optional one", name))
	}
	a := &positional{name: name, help: help, required: required, dst: new(string)}
	p.pos = append(p.pos, a)
	return a.dst
}

// Parse parses args, which should not include the program name. It returns
// ErrHelp if help was requested, or an error describing the first problem.
func (p *Parser) Parse(args []string) error {
	var positionals []string
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "--":
			positionals = append(positionals, args[i+1:]...)
			i = len(args)

		case strings.HasPrefix(arg, "--"):
			name, val, hasVal := strings.Cut(arg[2:], "=")
			if name == "help" && !hasVal {
				return ErrHelp
			}
			f := p.long[name]
			if f == nil {
				return fmt.Errorf("unknown flag --%s", name)
			}
			if !hasVal {
				if f.meta == "" {
					val = "true"
				} else if i++; i < len(args) {
					val = args[i]
				} else {
					return fmt.Errorf("flag --%s requires a value", name)
				}
			}
			if err := f.set(val); err != nil {
				return fmt.Errorf("invalid value %q for flag --%s: %v", val, name, err)
			}

		case len(arg) > 1 && arg[0] == '-' && !p.isNegativeNumber(arg):
			cluster := arg[1:]
			for j, r := range cluster {
				f := p.short[r]
				if f == nil {
					if r == 'h' {
						return ErrHelp
					}
					return fmt.Errorf("unknown flag -%c", r)
				}
				if f.meta == "" {
					f.set("true")
					continue
				}
				// A value flag takes the remainder of the cluster, or the next argument.
				val := cluster[j+utf8.RuneLen(r):]
				if val == "" {
					if i++; i >= len(args) {
						return fmt.Errorf("flag -%c requires a value", r)
					}
					val = args[i]
				}
				if err := f.set(val); err != nil {
					return fmt.Errorf("invalid value %q for flag -%c: %v", val, r, err)
				}
				break
			}

		default:
			positionals = append(positionals, arg)
		}
	}

	for i, a := range p.pos {
		if i < len(positionals) {
			*a.dst = positionals[i]
		} else if a.required {
			return fmt.Errorf("missing required argument <%s>", a.name)
		}
	}
	if len(positionals) > len(p.pos) {
		extra := positionals[len(p.pos):]
		if p.rest == nil {
			return fmt.Errorf("unexpected argument %q", extra[0])
		}
		*p.rest = extra
	}
	return nil
}

// isNegativeNumber reports whether arg should be treated as a positional
// number such as -5 rather than as short flags.
func (p *Parser) isNegativeNumber(arg string) bool {
	r, _ := utf8.DecodeRuneInString(arg[1:])
	if p.short[r] != nil {
		return false
	}
	_, err := strconv.ParseFloat(arg, 64)
	return err == nil
}

// MustParse parses os.Args. On --help it prints the help text and exits with
// status 0; on error it prints the error and exits with status 2.
func (p *Parser) MustParse() {
	err := p.Parse(os.Args[1:])
	if err == ErrHelp {
		fmt.Print(p.Help())
		os.Exit(0)
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s: %v\nTry '%s --help' for more information.\n", p.name, err, p.name)
		os.Exit(2)
	}
}

// Help returns the help message generated from the definitions.
func (p *Parser) Help() string {
	var b strings.Builder

	fmt.Fprintf(&b, "Usage: %s [options]", p.name)
	for _, a := range p.pos {
		if a.required {
			fmt.Fprintf(&b, " <%s>", a.name)
		} else {
			fmt.Fprintf(&b, " [%s]", a.name)
		}
	}
	if p.rest != nil {
		fmt.Fprintf(&b, " [%s...]", p.restName)
	}
	b.WriteString("\n")

	if p.desc != "" {
		fmt.Fprintf(&b, "\n%s\n", p.desc)
	}

	var rows [][2]string
	for _, a := range p.pos {
		help := a.help
		if !a.required {
			help += " (optional)"
		}
		rows = append(rows, [2]string{a.name, help})
	}
	if p.rest != nil {
		rows = append(rows, [2]string{p.restName + "...", p.restHelp})
	}
	if len(rows) > 0 {
		b.WriteString("\nArguments:\n")
		writeRows(&b, rows)
	}

	rows = nil
	for _, f := range p.flags {
		left := "    --" + f.long
		if f.short != 0 {
			left = fmt.Sprintf("-%c, --%s", f.short, f.long)
		}
		if f.meta != "" {
			left += " <" + f.meta + ">"
		}
		help := f.help
		if f.def != "" {
			help += " (default " + f.def + ")"
		}
		rows = append(rows, [2]string{left, help})
	}
	// -h is only the help shortcut if the program hasn't claimed it.
	if p.short['h'] == nil {
		rows = append(rows, [2]string{"-h, --help", "show this help"})
	} else {
		rows = append(rows, [2]string{"    --help", "show this help"})
	}
	b.WriteString("\nOptions:\n")
	writeRows(&b, rows)

	return b.String()
}

func writeRows(b *strings.Builder, rows [][2]string) {
	width := 0
	for _, r := range rows {
		if n := utf8.RuneCountInString(r[0]); n > width {
			width = n
		}
	}
	for _, r := range rows {
		pad := width - utf8.RuneCountInString(r[0])
		line := "  " + r[0] + strings.Repeat(" ", pad) + "  " + r[1]
		b.WriteString(strings.TrimRight(line, " ") + "\n")
	}
}

package argparse

import (
	"reflect"
	"strings"
	"testing"
)

type opts struct {
	verbose, force *bool
	name           *string
	count          *int
	src, dst       *string
	rest           *[]string
}

func newParser() (*Parser, opts) {
	p := New("copy", "Copy things around.")
	o := opts{
		verbose: p.Bool("verbose", 'v', "enable verbose output"),
		force:   p.Bool("force", 'f', "overwrite existing files"),
		name:    p.String("name", 'n', "world", "name to use"),
		count:   p.Int("count", 'c', 1, "number of copies"),
		src:     p.Arg("src", "source file"),
		dst:     p.OptionalArg("dst", "destination file"),
		rest:    p.Rest("extra", "additional files"),
	}
	return p, o
}

func TestParse(t *testing.T) {
	tests := []struct {
		args    string
		verbose bool
		force   bool
		name    string
		count   int
		src     string
		dst     string
		rest    []string
	}{
		{args: "a", name: "world", count: 1, src: "a"},
		{args: "--verbose --name bob --count 3 a b", verbose: true, name: "bob", count: 3, src: "a", dst: "b"},
		{args: "--name=bob --count=3 a", name: "bob", count: 3, src: "a"},
		{args: "--name= a", name: "", count: 1, src: "a"},
		{args: "-v -n bob -c 3 a", verbose: true, name: "bob", count: 3, src: "a"},
		{args: "-vf a", verbose: true, force: true, name: "world", count: 1, src: "a"},
		{args: "-vfnbob a", verbose: true, force: true, name: "bob", count: 1, src: "a"},
		{args: "-vc 3 a", verbose: true, name: "world", count: 3, src: "a"},
		{args: "a -v b --force c d", verbose: true, force: true, name: "world", count: 1, src: "a", dst: "b", rest: []string{"c", "d"}},
		{args: "--verbose=false -f a", force: true, name: "world", count: 1, src: "a"},
		{args: "-v -- -f --name", verbose: true, name: "world", count: 1, src: "-f", dst: "--name"},
		{args: "--count -5 -3 -", name: "world", count: -5, src: "-3", dst: "-"},
		{args: "--name --verbose a", name: "--verbose", count: 1, src: "a"},
		{args: "-v a -v --count 1 --count 2", verbose: true, name: "world", count: 2, src: "a"},
	}
	for _, tt := range tests {
		p, o := newParser()
		if err := p.Parse(strings.Fields(tt.args)); err != nil {
			t.Errorf("%q: unexpected error: %v", tt.args, err)
			continue
		}
		if *o.verbose != tt.verbose || *o.force != tt.force || *o.name != tt.name || *o.count != tt.count {
			t.Errorf("%q: flags = verbose %v, force %v, name %q, count %d", tt.args, *o.verbose, *o.force, *o.name, *o.count)
		}
		if *o.src != tt.src || *o.dst != tt.dst || !reflect.DeepEqual(*o.rest, tt.rest) {
			t.Errorf("%q: positionals = src %q, dst %q, rest %q", tt.args, *o.src, *o.dst, *o.rest)
		}
	}
}

func TestParseErrors(t *testing.T) {
	tests := []struct{ args, want string }{
		{"", "missing required argument <src>"},
		{"--nope a", "unknown flag --nope"},
		{"-vx a", "unknown flag -x"},
		{"a --name", "flag --name requires a value"},
		{"a -vn", "flag -n requires a value"},
		{"--count abc a", `invalid value "abc" for flag --count: expected an integer`},
		{"-cabc a", `invalid value "abc" for flag -c: expected an integer`},
		{"--verbose=maybe a", `invalid value "maybe" for flag --verbose: expected true or false`},
	}
	for _, tt := range tests {
		p, _ := newParser()
		err := p.Parse(strings.Fields(tt.args))
		if err == nil || err.Error() != tt.want {
			t.Errorf("%q: error = %v, want %q", tt.args, err, tt.want)
		}
	}
}

func TestUnexpectedArgument(t *testing.T) {
	p := New("prog", "")
	p.Arg("file", "input file")
	err := p.Parse([]string{"a", "b"})
	if err == nil || err.Error() != `unexpected argument "b"` {
		t.Errorf("error = %v", err)
	}
}

func TestHelpRequested(t *testing.T) {
	for _, args := range []string{"--help", "-h", "a -vh", "--nope --help"} {
		p, _ := newParser()
		err := p.Parse(strings.Fields(args))
		if args == "--nope --help" {
			if err == ErrHelp {
				t.Errorf("%q: errors before --help should win", args)
			}
			continue
		}
		if err != ErrHelp {
			t.Errorf("%q: error = %v, want ErrHelp", args, err)
		}
	}

	// A program may claim -h for itself; --help still works.
	p := New("prog", "")
	host := p.String("host", 'h', "", "host to connect to")
	if err := p.Parse([]string{"-h", "example.com"}); err != nil || *host != "example.com" {
		t.Errorf("host = %q, err = %v", *host, err)
	}
	if err := p.Parse([]string{"--help"}); err != ErrHelp {
		t.Errorf("error = %v, want ErrHelp", err)
	}
	if !strings.Contains(p.Help(), "      --help") || strings.Contains(p.Help(), "-h, --help") {
		t.Errorf("help should not advertise -h:\n%s", p.Help())
	}
}

func TestHelp(t *testing.T) {
	p, _ := newParser()
	p.Bool("dry-run", 0, "print actions without performing them")
	want := `Usage: copy [options] <src> [dst] [extra...]

Copy things around.

Arguments:
  src       source file
  dst       destination file (optional)
  extra...  additional files

Options:
  -v, --verbose        enable verbose output
  -f, --force          overwrite existing files
  -n, --name <string>  name to use (default "world")
  -c, --count <int>    number of copies (default 1)
      --dry-run        print actions without performing them
  -h, --help           show this help
`
	if got := p.Help(); got != want {
		t.Errorf("help mismatch\ngot:\n%s\nwant:\n%s", got, want)
	}
}

func TestBadDefinitionsPanic(t *testing.T) {
	tests := map[string]func(p *Parser){
		"duplicate long":          func(p *Parser) { p.Bool("a", 0, ""); p.Bool("a", 0, "") },
		"duplicate short":         func(p *Parser) { p.Bool("a", 'x', ""); p.Bool("b", 'x', "") },
		"reserved help":           func(p *Parser) { p.Bool("help", 0, "") },
		"empty name":              func(p *Parser) { p.Bool("", 0, "") },
		"required after optional": func(p *Parser) { p.OptionalArg("a", ""); p.Arg("b", "") },
	}
	for name, define := range tests {
		func() {
			defer func() {
				if recover() == nil {
					t.Errorf("%s: expected panic", name)
				}
			}()
			define(New("prog", ""))
		}()
	}
}

package main

import (
	"fmt"

	"argparse"
)

func main() {
	p := argparse.New("greet", "Print a greeting to each person named.")
	shout := p.Bool("shout", 's', "print in upper case")
	greeting := p.String("greeting", 'g', "Hello", "greeting to use")
	times := p.Int("times", 't', 1, "number of times to repeat")
	first := p.Arg("name", "person to greet")
	others := p.Rest("others", "more people to greet")
	p.MustParse()

	for _, name := range append([]string{*first}, *others...) {
		for i := 0; i < *times; i++ {
			if *shout {
				fmt.Printf("%S, %S!\n", *greeting, name)
			} else {
				fmt.Printf("%s, %s!\n", *greeting, name)
			}
		}
	}
}

